#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_CONTAINERS 64
#define MAX_KEY_LEN 64
#define MAX_VAL_LEN 256
#define MAX_FIELDS 16

typedef struct {
    char key[MAX_KEY_LEN];
    char value[MAX_VAL_LEN];
} ConfigField;

typedef struct {
    char container_id[64];
    char image[128];
    char network_mode[32];
    int cpu_shares;
    int memory_mb;
    bool privileged;
    bool host_pid;
    bool readonly_rootfs;
    char capabilities[256];
    ConfigField extra_fields[MAX_FIELDS];
    int extra_count;
} ContainerSpec;

typedef struct {
    bool allow_privileged;
    bool allow_host_pid;
    bool allow_cap_admin;
    bool enforce_readonly;
    int max_cpu_shares;
    int max_memory_mb;
} FeatureFlags;

static FeatureFlags g_flags = {
    .allow_privileged = false,
    .allow_host_pid = false,
    .allow_cap_admin = false,
    .enforce_readonly = true,
    .max_cpu_shares = 1024,
    .max_memory_mb = 4096
};

static ContainerSpec g_containers[MAX_CONTAINERS];
static int g_container_count = 0;

/* Field offset registry for dynamic field assignment */
typedef struct {
    const char *name;
    size_t offset;
    char type; /* 's'=string, 'i'=int, 'b'=bool */
    size_t size;
} FieldDescriptor;

static const FieldDescriptor spec_fields[] = {
    {"container_id", offsetof(ContainerSpec, container_id), 's', 64},
    {"image",        offsetof(ContainerSpec, image),        's', 128},
    {"network_mode", offsetof(ContainerSpec, network_mode), 's', 32},
    {"cpu_shares",   offsetof(ContainerSpec, cpu_shares),   'i', sizeof(int)},
    {"memory_mb",    offsetof(ContainerSpec, memory_mb),    'i', sizeof(int)},
    {"privileged",   offsetof(ContainerSpec, privileged),   'b', sizeof(bool)},
    {"host_pid",     offsetof(ContainerSpec, host_pid),     'b', sizeof(bool)},
    {"readonly_rootfs", offsetof(ContainerSpec, readonly_rootfs), 'b', sizeof(bool)},
    {"capabilities", offsetof(ContainerSpec, capabilities), 's', 256},
    {NULL, 0, 0, 0}
};

/* Security-sensitive fields that require feature flag checks */
static const char *restricted_fields[] = {
    "privileged", "host_pid", "capabilities", NULL
};

static bool is_restricted_field(const char *name) {
    for (int i = 0; restricted_fields[i]; i++) {
        if (strcmp(restricted_fields[i], name) == 0)
            return true;
    }
    return false;
}

static bool check_feature_gate(const char *field, const char *value) {
    if (strcmp(field, "privileged") == 0 && strcmp(value, "true") == 0)
        return g_flags.allow_privileged;
    if (strcmp(field, "host_pid") == 0 && strcmp(value, "true") == 0)
        return g_flags.allow_host_pid;
    if (strcmp(field, "capabilities") == 0 && strstr(value, "CAP_SYS_ADMIN"))
        return g_flags.allow_cap_admin;
    return true;
}

static const FieldDescriptor *find_field(const char *name) {
    for (int i = 0; spec_fields[i].name; i++) {
        if (strcmp(spec_fields[i].name, name) == 0)
            return &spec_fields[i];
    }
    return NULL;
}

static void assign_field(ContainerSpec *spec, const FieldDescriptor *fd, const char *value) {
    char *base = (char *)spec;
    switch (fd->type) {
        case 's':
            strncpy(base + fd->offset, value, fd->size - 1);
            (base + fd->offset)[fd->size - 1] = '\0';
            break;
        case 'i':
            *(int *)(base + fd->offset) = atoi(value);
            break;
        case 'b':
            *(bool *)(base + fd->offset) = (strcmp(value, "true") == 0);
            break;
    }
}

/*
 * apply_spec_update: applies a batch of key=value pairs to a container spec.
 * Enforces feature gates on restricted fields.
 * Returns 0 on success, -1 on policy violation.
 */
int apply_spec_update(ContainerSpec *spec, const char *pairs[], int count) {
    /* Phase 1: Validate all restricted fields against feature gates */
    for (int i = 0; i < count; i++) {
        char key[MAX_KEY_LEN], val[MAX_VAL_LEN];
        const char *eq = strchr(pairs[i], '=');
        if (!eq) continue;
        size_t klen = eq - pairs[i];
        if (klen >= MAX_KEY_LEN) continue;
        strncpy(key, pairs[i], klen);
        key[klen] = '\0';
        strncpy(val, eq + 1, MAX_VAL_LEN - 1);
        val[MAX_VAL_LEN - 1] = '\0';

        if (is_restricted_field(key)) {
            if (!check_feature_gate(key, val)) {
                fprintf(stderr, "Policy violation: %s=%s blocked by feature gate\n", key, val);
                return -1;
            }
        }
    }

    /* Phase 2: Apply all fields (validated above) */
    for (int i = 0; i < count; i++) {
        char key[MAX_KEY_LEN], val[MAX_VAL_LEN];
        const char *eq = strchr(pairs[i], '=');
        if (!eq) continue;
        size_t klen = eq - pairs[i];
        if (klen >= MAX_KEY_LEN) continue;
        strncpy(key, pairs[i], klen);
        key[klen] = '\0';
        strncpy(val, eq + 1, MAX_VAL_LEN - 1);
        val[MAX_VAL_LEN - 1] = '\0';

        const FieldDescriptor *fd = find_field(key);
        if (fd) {
            assign_field(spec, fd, val);
        }
    }
    return 0;
}

/*
 * create_container: creates a new container from user-supplied config pairs.
 * Applies defaults then user overrides with policy enforcement.
 */
int create_container(const char *pairs[], int count) {
    if (g_container_count >= MAX_CONTAINERS) return -1;

    ContainerSpec *spec = &g_containers[g_container_count];
    memset(spec, 0, sizeof(ContainerSpec));

    /* Secure defaults */
    spec->privileged = false;
    spec->host_pid = false;
    spec->readonly_rootfs = g_flags.enforce_readonly;
    spec->cpu_shares = 512;
    spec->memory_mb = 256;
    strncpy(spec->network_mode, "bridge", sizeof(spec->network_mode) - 1);

    int rc = apply_spec_update(spec, pairs, count);
    if (rc == 0) {
        g_container_count++;
    }
    return rc;
}

/* Example usage / test harness */
int main(int argc, char *argv[]) {
    /* Simulate an API request with user-supplied fields */
    const char *user_request[] = {
        "container_id=web-app-01",
        "image=nginx:latest",
        "cpu_shares=256",
        "memory_mb=512",
        "readonly_rootfs=false",
        "privileged=true"
    };
    int field_count = sizeof(user_request) / sizeof(user_request[0]);

    printf("Feature flags: privileged=%d, host_pid=%d, cap_admin=%d\n",
           g_flags.allow_privileged, g_flags.allow_host_pid, g_flags.allow_cap_admin);

    int result = create_container(user_request, field_count);
    if (result == 0) {
        ContainerSpec *c = &g_containers[0];
        printf("Container created: id=%s privileged=%d host_pid=%d readonly=%d\n",
               c->container_id, c->privileged, c->host_pid, c->readonly_rootfs);
    } else {
        printf("Container creation blocked by policy\n");
    }
    return 0;
}
